/** Compare dotted versions numerically (missing parts are 0). */
export function compareNative(a: string, b: string): number {
    const pa = a.split('.').map(x => Number(x) || 0);
    const pb = b.split('.').map(x => Number(x) || 0);
    for (let i = 0; i < Math.max(pa.length, pb.length); i++) {
        const d = (pa[i] || 0) - (pb[i] || 0);
        if (d) return d < 0 ? -1 : 1;
    }
    return 0;
}

/** The policy channel a client reads: Debug builds (`dev`) follow beta. */
export function policyChannel(c: ClientPolicyChannel | undefined): 'stable' | 'beta' {
    return c === 'beta' || c === 'dev' ? 'beta' : 'stable';
}

/** The effective sim floor: the policy's, never below the oldest sim the backend still replays. */
export function effectiveMinSim(policyMin: number | null, acceptedSims: readonly number[] | null): number | null {
    const backendMin = acceptedSims && acceptedSims.length ? Math.min(...acceptedSims) : null;
    if (policyMin === null) return backendMin;
    if (backendMin === null) return policyMin;
    return Math.max(policyMin, backendMin);
}

/** A maintenance window that is on at `now`. */
export function maintenanceOn(m: PolicyMaintenance | null | undefined, now: number): boolean {
    if (!m) return false;
    if (m.until === null) return true;
    const until = Date.parse(m.until);
    return Number.isNaN(until) || now < until;
}

export interface DecidePolicyInput {
    /** The signed policy file for the client's platform and compat, or null (web, Mac, or none reachable). */
    policy: PolicyFile | null;
    /** Overrides the policy channel's entry (the web build's `version.json`); undefined = the policy's entry. */
    latest?: PolicyChannelEntry | null;
    /** The sims the backend replays (`SIM_VERSIONS`), or null when unknown (the shell's static fallback). */
    acceptedSims: readonly number[] | null;
    client: ClientPolicyQuery;
    now: number;
}

const toLatest = (e: PolicyChannelEntry): ClientPolicyLatest => ({
    version: e.version,
    seq: e.seq,
    simVersion: e.simVersion,
    minNative: e.minNative,
});

/**
 * The decision (FORCE-UPDATE.md §3.3), in order:
 * 1. a maintenance window is on → `maintenance`;
 * 2. the native shell is below `minCompat` → `store`;
 * 3. the client's sim is not replayed by the backend, or is below the floor → `update` when the channel's latest
 *    bundle fixes it and this native shell may run it (the web always reloads), else `store`;
 * 4. the channel's latest is another bundle that is newer (or a rollback) and required by now → `update` (`store`
 *    when it needs a newer native shell);
 * 5. otherwise `ok`, with `latest` so a newer optional bundle can still download in the background.
 * A client that says nothing about itself gets `ok`. Pure.
 */
export function decidePolicy(o: DecidePolicyInput): ClientPolicyDecision {
    const { policy, client, now } = o;
    const accepted = o.acceptedSims && o.acceptedSims.length ? o.acceptedSims : null;
    if (policy && maintenanceOn(policy.maintenance, now)) return { action: 'maintenance', reason: 'maintenance', latest: null };
    const entry: PolicyChannelEntry | null =
        o.latest !== undefined ? o.latest : policy ? policy.channels[policyChannel(client.channel)] ?? null : null;
    const latest = entry ? toLatest(entry) : null;
    if (policy && client.compat !== undefined && client.compat < policy.minCompat) {
        return { action: 'store', reason: 'compat-retired', latest };
    }
    const nativeOk = (e: PolicyChannelEntry): boolean =>
        client.native === undefined || compareNative(client.native, e.minNative) >= 0;
    const minSim = effectiveMinSim(policy ? policy.minSim : null, accepted);
    if (client.sim !== undefined) {
        const notAccepted = accepted !== null && accepted.indexOf(client.sim) < 0;
        const tooOld = minSim !== null && client.sim < minSim;
        if (notAccepted || tooOld) {
            const reason: ClientPolicyReason = notAccepted ? 'sim-not-accepted' : 'sim-too-old';
            if (client.platform === 'web') return { action: 'update', reason, latest };
            const fixes =
                !!entry &&
                entry.version !== client.bundle &&
                (accepted === null || accepted.indexOf(entry.simVersion) >= 0) &&
                (minSim === null || entry.simVersion >= minSim);
            if (fixes && entry && nativeOk(entry)) return { action: 'update', reason, latest };
            return { action: 'store', reason: fixes ? 'native-too-old' : reason, latest };
        }
    }
    if (entry && client.bundle !== undefined && entry.version !== client.bundle) {
        const other = entry.rollback || client.seq === undefined || entry.seq === 0 || entry.seq > client.seq;
        const from = Date.parse(entry.requiredFrom);
        const due = Number.isNaN(from) || now >= from;
        if (other && due) {
            if (!nativeOk(entry)) return { action: 'store', reason: 'native-too-old', latest };
            return { action: 'update', reason: entry.rollback ? 'rollback' : 'older-bundle', latest };
        }
    }
    return { action: 'ok', reason: 'current', latest };
}
